let scoreExample={experts:'80, 85, 90',peers:'70, 78, 80, 84, 96'};
function templateText(t){return '当前评分预设：'+ScoreRules.profile(Prep.getScoring()).label+'\n\n'+ruleText(t.text)}
function allTemplateText(){return window.HANDBOOK_DATA.templates.map(t=>t.title+'\n'+templateText(t)).join('\n\n────────────\n\n')}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function table(heads,rows){return '<div class="table-wrap"><table><thead><tr>'+heads.map(h=>'<th scope="col">'+escapeHTML(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+escapeHTML(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function refs(ids){return '<p class="caption">相关参考：'+ids.map(id=>'<a href="#sources" data-source="'+id+'">'+id+'</a>').join(' · ')+'</p>'}
function block(b){let html='<section class="panel"><h2>'+escapeHTML(b.title)+'</h2>';if(b.paragraph)html+='<p>'+escapeHTML(b.paragraph)+'</p>';if(b.list||b.ordered){let tag=b.ordered?'ol':'ul';html+='<'+tag+'>'+(b.list||b.ordered).map(t=>'<li>'+escapeHTML(t)+'</li>').join('')+'</'+tag+'>'}if(b.heads)html+=table(b.heads,b.rows);if(b.note)html+='<div class="note">'+escapeHTML(b.note)+'</div>';if(b.refs)html+=refs(b.refs);if(b.special==='schedule')html+=Prep.journeyScheduleHTML();if(b.special==='score')html+='<div class="form-grid"><label>3位专业评委总分（逗号分隔）<input id="expertScores" type="text" value="'+escapeHTML(scoreExample.experts)+'"></label><label>5支队伍互评总分（逗号分隔）<input id="peerScores" type="text" value="'+escapeHTML(scoreExample.peers)+'"></label></div><div class="actions"><button class="btn" id="calcScore">计算示例</button></div><div id="scoreResult" class="result-list" aria-live="polite">E = 85.00，P = 80.00，S = {{EXAMPLE_SCORE}}</div><p class="caption" style="margin-top:12px">适用于单轮正式评分或海选的{{SCORE_RATIO}}公式，不保存数据、不收正式评分。缺失分数不能当作0。</p>';if(b.special==='archive-schema')html+='<p class="small muted">以下是占位示例，不是真实参赛作品。公开数据不能包含联系方式、评审身份和测试账号密码。</p><pre class="code-block">'+escapeHTML(JSON.stringify({submission_id:'SUB-024',team_id:'T024',title:'作品名称',tagline:'60字以内简介',track:'从零创作',status:'prototype',summary:'问题、用户、方案与证据',event_contribution:'本届新增内容',baseline_commit:null,submitted_commit:'冻结SHA',submitted_at:'截止时间（含时区）',demo_url:'https://your-domain.example/demo',video_url:'https://your-domain.example/video',source_visibility:'private_to_judges',source_url:null,license:'作者填写',ai_disclosure:'工具及用途',members:['经同意公开的显示名'],known_limitations:'未完成项',display_consent:true,recording_consent:false,updated_at:'最后核对时间'},null,2))+'</pre>';return html+'</section>'}
window.HANDBOOK={};Object.entries(window.HANDBOOK_DATA.pages).forEach(function(entry){const key=entry[0],p=entry[1];window.HANDBOOK[key]=()=>title(p.number,p.title,p.intro)+p.blocks.map(block).join('')});
window.HANDBOOK.templates=function(){return title('08','把规则变成可以发出去的表单。','8份可复制模板。方括号内容由主办方填写；本页不收集报名、签署或正式评分，也不会保存你输入的个人信息。')+'<div class="panel"><div class="section-label"><h2>从个人报名到赛后回访</h2><button class="btn" data-download-all>下载整套模板</button></div><p class="small muted">所有必填/可选、公开/私密字段都应在真实表单中配置。逐人确认、留规则版本和回执；不要把只读模板当作已经完成的电子签署。</p></div>'+window.HANDBOOK_DATA.templates.map((t,i)=>'<details '+(i===0?'open':'')+'><summary>'+escapeHTML(t.title)+'</summary><div class="detail-body"><div class="template-box">'+escapeHTML(templateText(t))+'</div><div class="actions"><button class="btn secondary" data-copy="'+t.id+'">复制这份模板</button><button class="btn secondary" data-download="'+t.id+'">下载 TXT</button></div></div></details>').join('')};
window.HANDBOOK.sources=function(){return title('11','有出处的参考，有边界的借鉴。','覆盖中国社群、全球线上赛、大小型创作赛与活动筹备指南。赛制来源核对：2026-10-03；新增筹备指南：2026-10-04。历史活动不代表仍在报名；平台能力需用实际账号验证。')+'<div class="note"><strong>研究与建议分开：</strong>本站超过30队才海选、默认12队决赛、{{SCORE_RATIO}}权重、3+5点评承诺、匿名和申诉办法是拟定方案，并非参考赛事共同采用的标准。Vivi案例为当前查到最可能对应的活动，仍可根据具体链接修正。</div><div class="grid2">'+window.HANDBOOK_SOURCES.map(s=>'<article class="panel source-card" id="source-'+s.id+'"><span class="badge">'+escapeHTML(s.type)+'</span><h3>'+escapeHTML(s.name)+' <span class="source-id">'+s.id+'</span></h3><ul class="small">'+s.facts.map(f=>'<li>'+escapeHTML(f)+'</li>').join('')+'</ul><p class="muted">'+escapeHTML(s.boundary)+'</p>'+(s.unverified.length?'<p class="caption">未核实：'+escapeHTML(s.unverified.slice(0,4).join('、'))+'。</p>':'')+'<span class="caption">'+escapeHTML(s.date)+'</span><a class="source-link" href="'+escapeHTML(s.url)+'" target="_blank" rel="noopener noreferrer">查看原始规则 / 主办页面</a></article>').join('')+'</div><div class="note">来源分为主办方规则、官方社区转载和平台指南。未公开的互评算法、匿名办法、单队时长等不补写为事实。网站建议以本手册唯一版本为准，不直接拼接互相冲突的赛事条款。</div>'};
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function downloadText(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('已生成下载文件')}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('模板已复制')}catch(e){const a=document.createElement('textarea');a.value=text;document.body.appendChild(a);a.select();const ok=document.execCommand('copy');a.remove();toast(ok?'模板已复制':'请选中模板文本后手动复制')}}
window.afterRender=function(key){if(key==='templates'){document.querySelector('[data-download-all]')?.addEventListener('click',()=>downloadText('线上黑客松-全套模板-'+ScoreRules.profile(Prep.getScoring()).ratio.replace('/','-')+'.txt',allTemplateText()));document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>copyText(templateText(window.HANDBOOK_DATA.templates.find(t=>t.id===b.dataset.copy)))));document.querySelectorAll('[data-download]').forEach(b=>b.addEventListener('click',()=>{const t=window.HANDBOOK_DATA.templates.find(t=>t.id===b.dataset.download);downloadText(t.title+'-'+ScoreRules.profile(Prep.getScoring()).ratio.replace('/','-')+'.txt',templateText(t))}))}if(key==='scoring'){document.querySelector('#expertScores').addEventListener('input',e=>scoreExample.experts=e.target.value);document.querySelector('#peerScores').addEventListener('input',e=>scoreExample.peers=e.target.value);const calculateExample=()=>{const read=(id,n)=>{const raw=document.querySelector(id).value.trim();if(!raw)throw Error('请填入完整评分。');const parts=raw.split(/[,，]/).map(x=>x.trim());if(parts.length!==n||parts.some(x=>x===''))throw Error('请分别填入3个专业分和5个互评分。');const nums=parts.map(Number);if(nums.some(x=>!Number.isFinite(x)||x<0||x>100))throw Error('分数必须是0–100之间的数字。');return nums};try{const e=read('#expertScores',3),p=read('#peerScores',5).sort((a,b)=>a-b),E=e.reduce((a,b)=>a+b,0)/3,P=p[2],S=ScoreRules.score(E,P,Prep.getScoring());document.querySelector('#scoreResult').textContent='E = '+E.toFixed(2)+'，P = '+P.toFixed(2)+'，S = '+S.toFixed(2)}catch(e){document.querySelector('#scoreResult').textContent=e.message}};document.querySelector('#calcScore').addEventListener('click',calculateExample);calculateExample()}if(key==='sources'&&window.pendingSource){const id=window.pendingSource;window.pendingSource=null;setTimeout(()=>document.getElementById('source-'+id)?.scrollIntoView({behavior:'smooth',block:'start'}),30)}};
document.addEventListener('click',e=>{const a=e.target.closest('[data-source]');if(a){window.pendingSource=a.dataset.source;if(location.hash==='#sources'){window.afterRender('sources')}}});
